1	import type { PostRecord } from "./blog";
2	
3	export type RssInput = {
4	  siteUrl: string;
5	  siteName: string;
6	  description: string;
7	  posts: readonly PostRecord[];
8	};
9	
10	export type SitemapEntry = {
11	  url: string;
12	  lastModified: string;
13	};
14	
15	function escapeXml(value: string): string {
16	  return value
17	    .replaceAll("&", "&amp;")
18	    .replaceAll("<", "&lt;")
19	    .replaceAll(">", "&gt;")
20	    .replaceAll('"', "&quot;")
21	    .replaceAll("'", "&apos;");
22	}
23	
24	export function buildRssXml({
25	  siteUrl,
26	  siteName,
27	  description,
28	  posts,
29	}: RssInput): string {
30	  const items = posts
31	    .slice()
32	    .sort(
33	      (a, b) =>
34	        new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
35	    )
36	    .map(
37	      (post) => `    <item>
38	      <title>${escapeXml(post.title)}</title>
39	      <link>${escapeXml(`${siteUrl}/blog/${encodeURIComponent(post.slug)}`)}</link>
40	      <guid>${escapeXml(`${siteUrl}/blog/${encodeURIComponent(post.slug)}`)}</guid>
41	      <description>${escapeXml(post.summary)}</description>
42	      <pubDate>${new Date(post.publishedAt).toUTCString()}</pubDate>
43	    </item>`,
44	    )
45	    .join("\n");
46	
47	  return `<?xml version="1.0" encoding="UTF-8"?>
48	<rss version="2.0">
49	  <channel>
50	    <title>${escapeXml(siteName)}</title>
51	    <link>${siteUrl}</link>
52	    <description>${escapeXml(description)}</description>
53	${items ? `${items}\n` : ""}  </channel>
54	</rss>`;
55	}
56	
57	export function buildSitemapEntries({
58	  siteUrl,
59	  posts,
60	}: {
61	  siteUrl: string;
62	  posts: readonly PostRecord[];
63	}): SitemapEntry[] {
64	  const today = new Date().toISOString().slice(0, 10);
65	  // `/blog` 404s until a Post is published; `/projects` is always a page.
66	  const routes = posts.length > 0 ? ["", "/projects", "/blog"] : ["", "/projects"];
67	  const core = routes.map((route) => ({
68	    url: `${siteUrl}${route}`,
69	    lastModified: today,
70	  }));
71	
72	  const postEntries = posts.map((post) => ({
73	    url: `${siteUrl}/blog/${encodeURIComponent(post.slug)}`,
74	    lastModified: post.publishedAt,
75	  }));
76	
77	  return [...core, ...postEntries];
78	}
79	
80	export function ogImagePath(title: string): string {
81	  return `/og?title=${encodeURIComponent(title)}`;
82	}
