1	"use client";
2	
3	import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
4	import type { CSSProperties } from "react";
5	import { formatCompactTokens, type ActivityDay } from "@/lib/ai-activity";
6	import {
7	  formatActivityDate,
8	  LEVEL_ALPHA,
9	  type ActivityWeek,
10	} from "@/lib/activity-grid";
11	
12	/** The rail the strip is drawn on, and what a day may cost inside it. */
13	const CELL_GAP = 2;
14	const CELL_MIN = 12;
15	const CELL_MAX = 18;
16	
17	/** How long a held arrow key waits before it starts walking, and how fast. */
18	const REPEAT_DELAY_MS = 300;
19	const REPEAT_INTERVAL_MS = 55;
20	
21	const STEP_BY_KEY: Record<string, number> = {
22	  ArrowLeft: -7,
23	  ArrowRight: 7,
24	  ArrowUp: -1,
25	  ArrowDown: 1,
26	};
27	
28	function cellLabel(day: ActivityDay): string {
29	  return `${formatActivityDate(day.date)}: ${formatCompactTokens(day.tokens)} tokens`;
30	}
31	
32	/**
33	 * A single tab stop with arrow-key traversal (listbox pattern), so a year of
34	 * cells never becomes a year of tab stops.
35	 *
36	 * The caption lives here too. It reads out the day under the cursor, and the
37	 * cursor is this component's state — lifting it to the section would mean
38	 * making the whole figure a client component to move one line of text.
39	 */
40	export function ActivityGrid({ weeks }: { weeks: readonly ActivityWeek[] }) {
41	  const gridId = useId();
42	  const slots = useMemo(() => weeks.flatMap((week) => week.cells), [weeks]);
43	  const lastFilled = useMemo(
44	    () => slots.reduce((last, slot, i) => (slot ? i : last), 0),
45	    [slots],
46	  );
47	  const [active, setActive] = useState<number | null>(null);
48	  const scrollRef = useRef<HTMLDivElement>(null);
49	
50	  // The largest whole-pixel square the rail can hold. Whole pixels because a
51	  // fractional track rounds unevenly — one week 12px wide, the next 13 — and
52	  // on a grid of squares that reads as a wobble rather than as a measurement.
53	  // Measured rather than guessed: the rail is a different width on a phone,
54	  // and the answer has to be a length before the browser can lay any of it out.
55	  const [cellSize, setCellSize] = useState(CELL_MIN);
56	
57	  useEffect(() => {
58	    const strip = scrollRef.current;
59	    if (!strip) return;
60	    const measure = () => {
61	      const style = getComputedStyle(strip);
62	      const rail =
63	        strip.clientWidth -
64	        parseFloat(style.paddingInlineStart) -
65	        parseFloat(style.paddingInlineEnd) -
66	        // The grid's own gutter, kept for the focus ring.
67	        6;
68	      const fits = Math.floor(
69	        (rail - (weeks.length - 1) * CELL_GAP) / weeks.length,
70	      );
71	      setCellSize(Math.min(CELL_MAX, Math.max(CELL_MIN, fits)));
72	    };
73	    measure();
74	    const observer = new ResizeObserver(measure);
75	    observer.observe(strip);
76	    return () => observer.disconnect();
77	  }, [weeks.length]);
78	
79	  // When the record is genuinely wider than the rail, the end of it is the
80	  // part worth opening on — today is the last column. A rail that is short by
81	  // only a few pixels is left where it is: scrolling it would push the first
82	  // week under the edge fade for nothing.
83	  useEffect(() => {
84	    const strip = scrollRef.current;
85	    if (!strip) return;
86	    const overflow = strip.scrollWidth - strip.clientWidth;
87	    if (overflow > 64) strip.scrollLeft = strip.scrollWidth;
88	    // `cellSize` is what decides whether there is an overflow at all, so the
89	    // rail is only worth opening on its end once that has been measured.
90	  }, [weeks, cellSize]);
91	
92	  const move = useCallback(
93	    (delta: number) => {
94	      setActive((current) => {
95	        const next = (current ?? lastFilled) + delta;
96	        if (next < 0 || next >= slots.length || !slots[next]) return current;
97	        return next;
98	      });
99	    },
100	    [lastFilled, slots],
101	  );
102	
103	  // Held keys walk on our own clock rather than the operating system's. The
104	  // native repeat rate is a user preference measured in tenths of a second,
105	  // which on a 365-cell grid is a key you hold for half a minute.
106	  const repeat = useRef<{ key: string; timers: number[] }>(null);
107	
108	  const stopRepeat = useCallback(() => {
109	    repeat.current?.timers.forEach(clearTimeout);
110	    repeat.current?.timers.forEach(clearInterval);
111	    repeat.current = null;
112	  }, []);
113	
114	  useEffect(() => stopRepeat, [stopRepeat]);
115	
116	  return (
117	    <>
118	      {/* The full record always renders; on a narrow viewport it is reached by
119	          dragging the strip sideways rather than by dropping half of it.
120	          A fragment, not a wrapper: `figcaption` has to be a direct child of
121	          the `figure` the section draws around this. */}
122	      <div className="py-4">
123	        <div ref={scrollRef} className="activity-scroll">
124	          <div
125	            role="listbox"
126	            tabIndex={0}
127	            aria-label="Daily token usage"
128	            aria-activedescendant={
129	              active !== null && slots[active] ? `${gridId}-${active}` : undefined
130	            }
131	            className="activity-grid"
132	            style={
133	              {
134	                "--weeks": weeks.length,
135	                "--cell-size": `${cellSize}px`,
136	              } as CSSProperties
137	            }
138	            onFocus={() => setActive((current) => current ?? lastFilled)}
139	            onBlur={() => {
140	              stopRepeat();
141	              setActive(null);
142	            }}
143	            onMouseLeave={() => setActive(null)}
144	            onKeyUp={(event) => {
145	              if (repeat.current?.key === event.key) stopRepeat();
146	            }}
147	            onKeyDown={(event) => {
148	              const step = STEP_BY_KEY[event.key];
149	              if (!step) return;
150	              event.preventDefault();
151	              // The OS sends its own repeats once the key is held; ours are
152	              // already running, so those are dropped on the floor.
153	              if (event.repeat) return;
154	              stopRepeat();
155	              move(step);
156	              const timers: number[] = [];
157	              timers.push(
158	                window.setTimeout(() => {
159	                  timers.push(
160	                    window.setInterval(() => move(step), REPEAT_INTERVAL_MS),
161	                  );
162	                }, REPEAT_DELAY_MS),
163	              );
164	              repeat.current = { key: event.key, timers };
165	            }}
166	          >
167	            {weeks.map((week, weekIndex) => (
168	              <div key={week.key} className="activity-col">
169	                {week.monthLabel ? (
170	                  <span className="activity-month">{week.monthLabel}</span>
171	                ) : null}
172	                {week.cells.map((day, dayIndex) => {
173	                  const index = weekIndex * 7 + dayIndex;
174	                  if (!day) {
175	                    return <div key={index} aria-hidden />;
176	                  }
177	                  return (
178	                    <div
179	                      key={index}
180	                      id={`${gridId}-${index}`}
181	                      role="option"
182	                      aria-selected={index === active}
183	                      aria-label={cellLabel(day)}
184	                      data-active={index === active}
185	                      onMouseEnter={() => setActive(index)}
186	                      className="activity-cell"
187	                      style={
188	                        {
189	                          "--level": LEVEL_ALPHA[day.intensity] ?? LEVEL_ALPHA[0],
190	                          "--col": weekIndex,
191	                        } as CSSProperties
192	                      }
193	                    />
194	                  );
195	                })}
196	              </div>
197	            ))}
198	          </div>
199	        </div>
200	      </div>
201	
202	      {/* The caption row: the plate number and, once there is a cursor on the
203	          grid, what is under it. The key sits right, where it stays out of the
204	          way of a line that changes on every cell. */}
205	      <figcaption className="flex flex-wrap items-center gap-x-4 gap-y-1 border-t border-line px-4 py-3 text-sm text-muted-foreground">
206	        <span className="flex min-w-0 items-center gap-2">
207	          <span className="tracking-wide text-muted-foreground/80">Fig. 2.</span>
208	          {active !== null && slots[active] ? (
209	            <span className="truncate font-mono text-xs tabular-nums">
210	              <span className="text-foreground">
211	                {formatCompactTokens(slots[active]!.tokens)}
212	              </span>{" "}
213	              · {formatActivityDate(slots[active]!.date)}
214	            </span>
215	          ) : null}
216	        </span>
217	
218	        <span className="ml-auto flex shrink-0 items-center gap-1 font-mono text-xs">
219	          less
220	          {LEVEL_ALPHA.map((alpha) => (
221	            <span
222	              key={alpha}
223	              aria-hidden
224	              className="size-2.5"
225	              style={{
226	                background: `color-mix(in oklab, var(--muted-foreground) ${alpha}, transparent)`,
227	              }}
228	            />
229	          ))}
230	          more
231	        </span>
232	      </figcaption>
233	    </>
234	  );
235	}
