1	import type { ActivityDay } from "@/lib/ai-activity";
2	
3	/**
4	 * Five steps of the neutral foreground. Intensity is opacity, never hue.
5	 * Lives here rather than in the grid component because the server-rendered
6	 * legend reads it too, and a `"use client"` module's exports are client
7	 * references on the server, not values.
8	 */
9	export const LEVEL_ALPHA = ["5%", "20%", "40%", "60%", "80%"] as const;
10	
11	export type ActivityWeek = {
12	  /** ISO date of the week's Sunday-aligned first slot. */
13	  key: string;
14	  /** Present only on the week that opens a new month. */
15	  monthLabel?: string;
16	  /** Sunday → Saturday. `null` pads the partial first and last weeks. */
17	  cells: (ActivityDay | null)[];
