--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  display: grid;
  /* Whole pixels, and the same number of them in every column. A fractional
     track (`1fr`) let the browser round one week to 12px and the next to 13,
     which on a grid of squares is visible as a wobble in every row — so the
     size is measured once, in whole pixels, and handed down as a length. */
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  /* The grid is one tab stop, but the thing that moves is the active cell, so
     the ring is drawn there instead of around all 365 of them. */
  outline: none;
  /* Room for that ring, so it cannot cross the panel's vertical rail. */
  padding-inline: 3px;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  padding-top: 1.05rem;
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;
}

/* The strip is wider than a phone, so it is dragged rather than trimmed. The edge fades are driven by the scroll position itself: each side
   is masked only while there is more grid past it, so a strip that fits shows
   no fade at all and a strip scrolled to its end stops advertising an end. */
@property --activity-fade-s {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --activity-fade-e {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@keyframes activity-fade-s {
  from {
    --activity-fade-s: 0px;
  }
  to {
    --activity-fade-s: var(--activity-fade);
  }
}
@keyframes activity-fade-e {
  from {
    --activity-fade-e: var(--activity-fade);
  }
  to {
    --activity-fade-e: 0px;
  }
}

.activity-scroll {
  --activity-fade: 2.5rem;
  display: flex;
  /* The same gutter every other row in the panel keeps, so the first and last
     week line up with the caption above them rather than with the rail. */
  padding-inline: 1rem;
  /* Centred while the year fits the rail, flush-left once it does not —
     `safe` is what keeps the first week reachable instead of centring it off
     the scrollable edge. */
  justify-content: safe center;
  overflow-x: auto;
  overflow-y: hidden;
  /* The grid is a drawing; a scrollbar drawn under it would read as part of
     the figure. The strip still scrolls by drag, wheel and keyboard. */
  scrollbar-width: none;
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--activity-fade-s),
    #000 calc(100% - var(--activity-fade-e)),
    transparent 100%
  );
  animation:
    activity-fade-s 1ms linear both,
    activity-fade-e 1ms linear both;
  animation-timeline: scroll(self inline), scroll(self inline);
  animation-range:
    0 var(--activity-fade),
    calc(100% - var(--activity-fade)) 100%;
}

.activity-scroll::-webkit-scrollbar {
  display: none;
}

.activity-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  width: var(--cell-size);
  height: var(--cell-size);
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  /* No transition on the marker. A cursor that fades in over a tenth of a
     second reads as the grid thinking about it; the cursor is where the
     pointer is, and that is true on the frame the pointer arrives. */
  outline: 1px solid transparent;
  outline-offset: 1px;
}

/* Pointer: a hairline marker. Keyboard: the site's own focus ring, moved onto
   the active descendant so focus keeps the same shape it has everywhere else. */
.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

.activity-grid:focus-visible .activity-cell[data-active="true"] {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

/* An empty frame rather than a fill. Only Figure 404 draws these now: inside
   the activity window an absent day is a measured zero, because the meter
   reads every session on the machine. */
.activity-cell[data-recorded="false"] {
  background: transparent;
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--muted-foreground) 16%, transparent);
}

/* ---------------------------------------------------------------------------
   A single sweep of light across a line of text, once, on load. The gradient
   is painted into the glyphs themselves and slid from right to left, so the
   highlight travels the line rather than the line changing colour. Spread is
   in `ch` so it scales with the type, and the background is twice the element
   plus two spreads wide so the sweep starts and ends fully off the text.
--------------------------------------------------------------------------- */
@keyframes shimmer-sweep {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: 0 0;
  }
}

