1	"use client";
2	
3	import { useSyncExternalStore } from "react";
4	import { ClockIcon } from "@/components/icons";
5	import { OverviewRow } from "@/components/overview-row";
6	import {
7	  formatZoneTime,
8	  handsPath,
9	  offsetLabel,
10	  zoneClock,
11	  zoneOffsetMinutes,
12	} from "@/lib/local-time";
13	
14	/**
15	 * One clock for the whole page, ticking only while something is watching it.
16	 *
17	 * It is an external store rather than a `useState` on a timer because the
18	 * server has no business guessing what time it is: `getServerSnapshot` returns
19	 * null, the row renders as a dial with no hands, and the real time arrives on
20	 * the first client render. That is the difference between a clock that is
21	 * briefly blank and a clock that is briefly wrong — this page is prerendered
22	 * and revalidates hourly, so a baked-in time could be an hour out.
23	 */
24	let listeners: (() => void)[] = [];
25	let ticking: ReturnType<typeof setInterval> | null = null;
26	let now: number | null = null;
27	
28	function subscribe(onTick: () => void) {
29	  listeners.push(onTick);
30	  if (!ticking) {
31	    now = Date.now();
32	    // A clock showing only minutes still has to turn over on the minute, and
33	    // there is no telling where inside one this mounted.
34	    ticking = setInterval(() => {
35	      now = Date.now();
36	      for (const listener of listeners) listener();
37	    }, 5_000);
38	  }
39	  return () => {
40	    listeners = listeners.filter((listener) => listener !== onTick);
41	    if (listeners.length === 0 && ticking) {
42	      clearInterval(ticking);
43	      ticking = null;
44	      now = null;
45	    }
46	  };
47	}
48	
49	/** What time it is where the author is, and how far that is from the reader. */
50	export function LocalTime({ zone }: { zone: string }) {
51	  const at = useSyncExternalStore(
52	    subscribe,
53	    () => now,
54	    () => null,
55	  );
56	  const reading = at === null ? null : read(zone, new Date(at));
57	
58	  return (
59	    <OverviewRow icon={<ClockIcon hands={reading?.hands} />}>
60	      {/* The dashes hold the width the time will take, so the row does not
61	          jump when the clock starts. */}
62	      <span className="tabular-nums">{reading?.time ?? "--:-- --"}</span>
63	      {/* The distance is context for the time beside it, not a second fact: a
64	          reader who has just been told the hour does not also need to be told
65	          how far away that hour is. */}
66	      {reading ? (
67	        <span aria-hidden className="text-muted-foreground">
68	          {` // ${reading.away}`}
69	        </span>
70	      ) : null}
71	    </OverviewRow>
72	  );
73	}
74	
75	function read(zone: string, at: Date) {
76	  const { hour, minute } = zoneClock(zone, at);
77	  return {
78	    time: formatZoneTime(zone, at),
79	    hands: handsPath(hour, minute),
80	    // `getTimezoneOffset` is minutes *behind* UTC, so adding it to the
81	    // author's offset gives the signed distance from the reader.
82	    away: offsetLabel(zoneOffsetMinutes(zone, at) + at.getTimezoneOffset()),
83	  };
84	}
