    [close, resolvedTheme, router, setTheme],
  );

  // Global shortcut.
  useEffect(() => {
    function onKey(event: KeyboardEvent) {
      if (event.key.toLowerCase() !== "k" || !(event.metaKey || event.ctrlKey))

    if (event.key.toLowerCase() !== "k" || !(event.metaKey || event.ctrlKey))
      return;
    event.preventDefault();
    if (open) close();
    else openFrom(document.activeElement as HTMLElement);
