/* ---------------------------------------------------------------------------
   Activity mosaic. Square blocks on a 2px gutter, no corner rounding — the
   grid is a measuring instrument, so its cells are not decorated. Intensity
   is carried by the neutral foreground at five opacities.

   Every measurement here is the reference's: a 12px block on a 2px gutter,
   under a 22px label band. They are not arbitrary — a rolling year at that
   size is a fixed 740px plate, the same shape every month of every year, which
   is the whole point of drawing a habit as a calendar. A cell that grew to
   fill the rail would make the same year a different picture each visit.
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  --label-size: 12px;
  display: grid;
  /* Whole pixels, and the same number of them in every column. A fractional
     track (`1fr`) let the browser round one week to 12px and the next to 13,
     which on a grid of squares is visible as a wobble in every row — so the
     size is measured once, in whole pixels, and handed down as a length. */
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  /* The grid is one tab stop, but the thing that moves is the active cell, so
     the ring is drawn there instead of around all 365 of them. */
  outline: none;
  /* Room for that ring, so it cannot cross the panel's vertical rail. */
  padding-inline: 3px;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  /* The label band: the type size plus the 8px of air the reference leaves
     under it, so the months sit above the plate rather than on it. */
  padding-top: calc(var(--label-size) + 8px);
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: var(--label-size);
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;

